import { useCallback, useEffect, useRef, useState } from 'react';
import { PageHeader } from '@kerfjs/ui/page-header';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import '@kerfjs/ui/layout.css';
import './workspace.css';

export type Item = { id: string; title: string };
export function ListWorkspace({ load, create }: {
 load: (signal: AbortSignal) => Promise<Item[]>; create: () => void;
}) {
 const [items, setItems] = useState<Item[] | null>(null);
 const [pending, setPending] = useState(true);
 const [error, setError] = useState<string | null>(null);
 const request = useRef<AbortController | null>(null);
 const refresh = useCallback(async () => {
   request.current?.abort();
   const controller = new AbortController(); request.current = controller;
   setPending(true); setError(null);
   try {
     const result = await load(controller.signal);
     if (!controller.signal.aborted) setItems(result);
   } catch {
     if (!controller.signal.aborted) setError('Could not load the list. Please try again.');
   } finally { if (!controller.signal.aborted) setPending(false); }
 }, [load]);
 useEffect(() => { void refresh(); return () => request.current?.abort(); }, [refresh]);
 return <main className="kui-layout list-workspace">
   <PageHeader>Projects</PageHeader>
   <section className="list-content" aria-label="Projects">
     <div className="list-actions"><button type="button" disabled={pending} onClick={() => void refresh()}>Refresh</button></div>
     <div role="status" aria-live="polite">{pending && <><LoadingSpinner aria-hidden="true" />{items === null ? 'Loading projects…' : 'Refreshing projects; showing the previous results.'}</>}</div>
     {error && <StateBanner role="alert"><strong>Unable to refresh projects.</strong><p>{error} {items !== null ? 'Previous results remain available.' : ''}</p><button type="button" onClick={() => void refresh()}>Try again</button></StateBanner>}
     {items !== null && (items.length ? <ul>{items.map(item => <li key={item.id}>{item.title}</li>)}</ul> :
       <EmptyState><h2>No projects yet</h2><p>Create your first project to begin.</p><button type="button" onClick={create}>Create project</button></EmptyState>)}
   </section>
 </main>;
}

